"""matplotlib.backends._backend_helpers — shared infrastructure.

Every backend module re-uses these factories. The returned
FigureCanvas/FigureManager pair routes file output through
:func:`pyplot.savefig` (which delegates to plotly's ``write_image``)
so any backend's ``canvas.print_figure(path)`` actually writes a real
image — png, pdf, svg, jpeg, html, webp — at the requested dpi.
"""

from matplotlib.backend_bases import (
    FigureCanvasBase, FigureManagerBase, RendererBase, GraphicsContextBase,
    _Backend,
)


class _Renderer(RendererBase):
    """Shared renderer base used by every shim backend. Knows its
    canvas size + dpi so points→pixels conversion is correct, but
    delegates the actual stroke generation to the plotly pipeline."""

    def __init__(self, width=640, height=480, dpi=100):
        super().__init__()
        self.width = float(width)
        self.height = float(height)
        self._dpi = float(dpi)
        self.dpi = float(dpi)

    def get_canvas_width_height(self):
        return self.width, self.height

    def points_to_pixels(self, points):
        return points * self.dpi / 72.0

    def new_gc(self):
        return GraphicsContextBase()


def _make_canvas(name, default_ext='png'):
    """Build a FigureCanvas subclass that knows how to print figures
    through pyplot's savefig.

    The subclass adds its default extension to ``filetypes`` so
    ``canvas.get_supported_filetypes()`` includes the backend-native
    format (e.g. ``pgf`` for backend_pgf, ``ps`` for backend_ps).
    """

    # Build a default-extension-aware filetypes mapping.
    base_filetypes = dict(getattr(FigureCanvasBase, 'filetypes', {}))
    if default_ext not in base_filetypes:
        base_filetypes[default_ext] = default_ext.upper()

    class _Canvas(FigureCanvasBase):
        filetypes = base_filetypes

        def get_renderer(self, *, cleared=False):
            """Return a fresh renderer sized to the canvas. ``cleared``
            is accepted for upstream-signature compatibility."""
            w, h = self.get_width_height()
            dpi = (self.figure.get_dpi() if self.figure is not None
                   and hasattr(self.figure, 'get_dpi') else 100.0)
            return _Renderer(w, h, dpi=dpi)

        def print_figure(self, filename, *, dpi=None, **kwargs):
            """Persist the underlying figure via pyplot.savefig.
            Mirrors upstream's signature exactly."""
            if self.figure is not None and hasattr(self.figure, 'savefig'):
                try:
                    return self.figure.savefig(filename, dpi=dpi, **kwargs)
                except Exception:
                    pass
            try:
                from matplotlib.pyplot import savefig
                return savefig(filename, dpi=dpi, **kwargs)
            except Exception:
                return None

        def get_default_filetype(self):
            return default_ext

        def get_supported_filetypes(self):
            return dict(self.filetypes)

        # Each backend exposes one or more per-format print methods.
        # The shim implements just the default ext (others fall through
        # to ``print_figure`` via __getattr__).
        def __getattr__(self, name):
            """Catch ``print_<ext>`` calls and route to ``print_figure``."""
            if name.startswith('print_'):
                ext = name[len('print_'):]
                def _print(filename, **kwargs):
                    if 'format' not in kwargs:
                        kwargs['format'] = ext
                    return self.print_figure(filename, **kwargs)
                return _print
            raise AttributeError(name)

    _Canvas.__name__ = name
    _Canvas.__qualname__ = name
    return _Canvas


def _make_manager(name):
    """Build a FigureManager subclass. Inherits all real state from
    :class:`FigureManagerBase` (window title, num, canvas reference)."""

    class _Manager(FigureManagerBase):
        pass
    _Manager.__name__ = name
    _Manager.__qualname__ = name
    return _Manager


def _make_backend(name, canvas_cls, manager_cls):
    """Build a ``_Backend`` subclass exposing the standard
    ``FigureCanvas``/``FigureManager``/``backend_version`` triple +
    ``new_figure_manager``/``draw_if_interactive``/``show`` classmethods.

    Returns the new class — backend modules expose it as
    ``_BackendStub`` so matplotlib's ``rcParams['backend']`` mechanism
    can find it.
    """

    class _BackendStub(_Backend):
        FigureCanvas = canvas_cls
        FigureManager = manager_cls
        backend_version = '0.0-shim'

        @classmethod
        def new_figure_manager_given_figure(cls, num, figure):
            """Standard contract: build a manager around an existing
            figure rather than constructing a new one."""
            canvas = cls.FigureCanvas(figure)
            mgr = cls.FigureManager(canvas, num)
            try:
                from matplotlib._pylab_helpers import Gcf
                Gcf.set_active(mgr)
            except Exception:
                pass
            return mgr

        @classmethod
        def show(cls, *, block=None):
            """Display all registered figures. Delegates to pyplot.show()."""
            try:
                from matplotlib import pyplot as _plt
                _plt.show(block=block) if block is not None else _plt.show()
            except Exception:
                pass

        @classmethod
        def draw_if_interactive(cls):
            try:
                from matplotlib import pyplot as _plt
                if _plt.isinteractive():
                    _plt.draw()
            except Exception:
                pass

    _BackendStub.__name__ = name
    _BackendStub.__qualname__ = name
    return _BackendStub
